// "Run the demo replies" lands here. Six invented replies in the shape Smartlead's EMAIL_REPLY
// webhook posts, one for each thing a reply can be: interested, not now, a referral, an
// unsubscribe, an out-of-office, and one only a person should answer.
const base = { event_type: 'EMAIL_REPLY', campaign_id: 'demo-campaign-a', campaign_name: 'Tier A (demo)' };
const replies = [
  { sl_email_lead_id: 'demo-1', sl_lead_email: 'user@example.com', to_name: 'Dana Reyes',
    subject: 'Re: Ledgerly and your Q4 pipeline',
    reply_message: { text: 'Thanks, the timing is actually good. Can you send a couple of slots for Thursday?\n\nOn Tue, 22 Sep, Sam wrote:\n> Hi Dana...' } },
  { sl_email_lead_id: 'demo-2', sl_lead_email: 'user@example.com', to_name: 'Marcus Obi',
    subject: 'Re: Freightline',
    reply_message: { text: 'Not a priority this quarter. Circle back in Q1 and we can look at it then.' } },
  { sl_email_lead_id: 'demo-3', sl_lead_email: 'user@example.com', to_name: 'Aisha Khan',
    subject: 'Re: Stackmart outbound',
    reply_message: { text: "I'm not the right person for this. Please loop in our RevOps lead, user@example.com." } },
  { sl_email_lead_id: 'demo-4', sl_lead_email: 'user@example.com', to_name: 'Nora Quinn',
    subject: 'Re: Vaultline',
    reply_message: { text: 'Please remove me from your list.' } },
  { sl_email_lead_id: 'demo-5', sl_lead_email: 'user@example.com', to_name: 'Grace Liu',
    subject: 'Automatic reply: Parcelhub',
    reply_message: { text: 'I am out of the office until Monday with limited access to email.' } },
  { sl_email_lead_id: 'demo-6', sl_lead_email: 'user@example.com', to_name: 'Priya Nair',
    subject: 'Re: Clinicflow',
    reply_message: { text: 'Who gave you my email address?' } }
];
return replies.map((r) => ({ json: { body: Object.assign({}, base, r), _source: 'demo replies (invented)' } }));

// CLAY OUTBOUND SCORING ENGINE — CONFIG
// Everything you might want to change lives in this one node. Nothing else in either
// workflow needs editing.
//
// The same config node ships in BOTH workflows ("01 score, enrich and route" and
// "02 classify replies and build the call list"). build.js regenerates both from this one
// file, and validate.js fails if they drift apart, so you never paste it between them.
//
// A blank key or id means that step is SKIPPED, never that the run fails. Both workflows run
// end to end on the invented demo prospects and demo replies, which is what lets this be
// shown on a screen-share before a single credential exists.

// ---------------------------------------------------------------- The safety switch
// Ships true. While it is true, nothing is written to Zoho and nothing is sent to a live
// Smartlead campaign or posted to the team: every payload is built in full and shown on a
// STOP node instead.
const TEST_RUN = true;
// Optional, only read while TEST_RUN is true. A Smartlead campaign id set here receives the
// pushes instead of the real campaigns (at most TEST_CAP leads). It can only ever REDIRECT a
// push, never cause a live one. Zoho is still not written in test mode.
const TEST_CAMPAIGN_ID = '';
const TEST_CAP = 3;

// ---------------------------------------------------------------- Mapping the Clay row
// Clay's HTTP API column posts one row as JSON to this workflow's webhook. You choose the key
// names in that column's body; list every name you might use for each field here, and the
// first one present on the row wins. Column names with spaces work as-is.
const CLAY_FIELDS = {
  clay_row_id:  ['clay_row_id', 'Clay Row ID', 'row_id', 'id'],
  first_name:   ['first_name', 'First Name', 'firstName'],
  last_name:    ['last_name', 'Last Name', 'lastName'],
  full_name:    ['full_name', 'Full Name', 'name', 'Name'],
  title:        ['title', 'Job Title', 'job_title', 'Title'],
  seniority:    ['seniority', 'Seniority'],
  email:        ['email', 'Work Email', 'work_email', 'Email'],
  phone:        ['phone', 'Mobile Phone', 'mobile_phone', 'Phone', 'Direct Phone'],
  linkedin_url: ['linkedin_url', 'LinkedIn URL', 'LinkedIn Profile', 'linkedin'],
  company:      ['company', 'Company Name', 'company_name', 'Company'],
  domain:       ['domain', 'Company Domain', 'company_domain', 'Website'],
  employees:    ['employees', 'Employee Count', 'employee_count', 'Company Size'],
  industry:     ['industry', 'Industry'],
  country:      ['country', 'Country', 'Location Country'],
  technologies: ['technologies', 'Technologies', 'Tech Stack', 'tech_stack'],
  // A Clay AI column's answer. If it names a persona from PERSONAS it is used as-is.
  ai_persona:   ['ai_persona', 'AI Persona', 'Persona']
};

// ---------------------------------------------------------------- Scoring (PLACEHOLDER)
// This table stands in for your own scoring method. It is a worked example, not your model:
// replace the rules, keep the shape. Each rule adds its points when its test matches;
// the total is clamped to 0..100.
//   equals    field value equals one of the values (case-insensitive)
//   contains  field value contains one of the words
//   between   a number between min and max, inclusive
//   any_of    a list field (technologies) contains any of the values
const SCORING = [
  { label: 'C-level',               field: 'seniority',    equals: ['c-level'],                  points: 30 },
  { label: 'VP',                    field: 'seniority',    equals: ['vp'],                       points: 25 },
  { label: 'Director / Head of',    field: 'seniority',    equals: ['director'],                 points: 20 },
  { label: 'Manager',               field: 'seniority',    equals: ['manager'],                  points: 10 },
  { label: 'Revenue-owning title',  field: 'title',        contains: ['sales', 'revenue', 'growth'], points: 10 },
  { label: 'Sweet-spot size',       field: 'employees',    between: [200, 1000],                 points: 25 },
  { label: 'Mid size',              field: 'employees',    between: [50, 199],                   points: 15 },
  { label: 'Large',                 field: 'employees',    between: [1001, 5000],                points: 15 },
  { label: 'Target industry',       field: 'industry',     contains: ['software', 'fintech', 'saas'], points: 20 },
  { label: 'Adjacent industry',     field: 'industry',     contains: ['logistics', 'healthcare'], points: 10 },
  { label: 'Uses a CRM we integrate', field: 'technologies', any_of: ['salesforce', 'hubspot', 'zoho'], points: 10 },
  { label: 'Core market',           field: 'country',      equals: ['united states', 'canada', 'united kingdom'], points: 5 }
];

// A disqualifier makes the prospect Reject whatever the score.
const DISQUALIFY = [
  { label: 'Student or intern',     field: 'title',     contains: ['intern', 'student'] },
  { label: 'Under 10 employees',    field: 'employees', between: [0, 9] },
  { label: 'Competitor',            field: 'domain',    equals: [] }
];

// Tier thresholds, highest first. Below the last one is Reject.
const TIERS = [
  { tier: 'A', min_score: 70 },
  { tier: 'B', min_score: 50 },
  { tier: 'C', min_score: 30 }
];

// Seniority when Clay did not send it, read off the title. First match wins.
const SENIORITY_FROM_TITLE = [
  { seniority: 'c-level',  words: ['chief', 'ceo', 'cro', 'cfo', 'coo', 'cto', 'founder', 'president'] },
  { seniority: 'vp',       words: ['vp', 'vice president'] },
  { seniority: 'director', words: ['director', 'head of'] },
  { seniority: 'manager',  words: ['manager', 'lead'] }
];

// Persona, first match on the title. A Clay AI column's answer (`ai_persona`) wins if it
// names one of these personas.
const PERSONAS = [
  { persona: 'Economic buyer',      words: ['ceo', 'founder', 'chief revenue', 'cro', 'vp sales', 'vp of sales', 'head of sales', 'sales director', 'director of sales'] },
  { persona: 'Operator',            words: ['revenue operations', 'revops', 'sales operations', 'operations'] },
  { persona: 'Technical evaluator', words: ['cto', 'it director', 'engineering', 'architect'] },
  { persona: 'Champion',            words: ['manager', 'lead'] }
];

// What a rep should do next, by tier and persona. `Tier|Persona` wins over `Tier|*`.
const RECOMMENDED_ACTION = {
  'A|Economic buyer': 'Call today, then sequence A',
  'A|*':              'Call within 24 hours, then sequence A',
  'B|*':              'Sequence B, call on any reply',
  'C|*':              'Nurture only: no enrichment, no sequence',
  'Reject|*':         'Do not contact'
};

// ---------------------------------------------------------------- Enrichment (the credits)
// Only these tiers are ever sent to paid enrichment, highest score first, and never more
// than ENRICH_BUDGET contacts in one run. The cap is enforced in code.
const ENRICH_TIERS  = ['A', 'B'];
const ENRICH_BUDGET = 4;
const CREDITS_PER_CONTACT = 1;
// Apollo's people/match reveals a verified work email (and a phone if asked). Blank key ->
// the demo enrichment stands in and the run says so.
const ENRICH_API_KEY = '';
const ENRICH_URL     = 'https://api.apollo.io/api/v1/people/match';
const REVEAL_PHONE   = false;   // phone reveals cost extra credits on most plans

// ---------------------------------------------------------------- Verification
// Every address is checked before it can reach a sending campaign. Anything the verifier did
// not answer counts as a hold: it fails closed.
const VERIFIER_API_KEY = '';
const VERIFIER_URL     = 'https://api.millionverifier.com/api/v3/';
const ACCEPT_STATUSES  = ['ok', 'valid', 'deliverable'];

// ---------------------------------------------------------------- Zoho CRM
// A Self Client in the Zoho API console gives a client id and secret; generate a refresh
// token with scope ZohoCRM.modules.ALL and ZohoCRM.coql.READ. The accounts base must match the
// data centre the org lives in (.com, .eu, .in, .com.au).
const ZOHO_CLIENT_ID     = '';
const ZOHO_CLIENT_SECRET = '';
const ZOHO_REFRESH_TOKEN = '';
const ZOHO_API_BASE      = 'https://www.zohoapis.com';
const ZOHO_ACCOUNTS_BASE = 'https://accounts.zoho.com';
const ZOHO_API_VERSION   = 'v8';
// Leads are upserted, matched on these fields in order, so a re-posted Clay row updates the
// lead instead of duplicating it.
const ZOHO_DUPLICATE_CHECK = ['Email'];
// Empty means Zoho's own workflow rules do NOT fire on these writes. Add 'workflow' to let them.
const ZOHO_TRIGGERS = [];
const LEAD_STATUS_BY_TIER = { A: 'Qualified - A', B: 'Qualified - B', C: 'Nurture' };
// Custom field API names from Zoho (Setup > Developer Hub > APIs > API names). Blank ->
// that field is not written.
const ZOHO_FIELDS = {
  fit_score: '',          // e.g. Fit_Score (number)
  tier: '',               // e.g. Fit_Tier (picklist A/B/C)
  persona: '',            // e.g. Persona
  recommended_action: '', // e.g. Recommended_Action
  clay_row_id: ''         // e.g. Clay_Row_ID
};
// Who owns a tier in Zoho (user ids). Blank -> Zoho's default owner.
const OWNER_BY_TIER = { A: '', B: '', C: '' };
// Reply states written back by workflow 02.
const REPLY_STATUS = {
  interested: 'Replied - Interested',
  not_now:    'Replied - Not now',
  referral:   'Replied - Referral',
  unsubscribe:'Unsubscribed',
  needs_human:'Replied - Needs review'
};

// ---------------------------------------------------------------- Smartlead
const SMARTLEAD_API_KEY  = '';
const SMARTLEAD_API_BASE = 'https://server.smartlead.ai/api/v1';
// One campaign per tier. Blank -> that tier is not pushed (C is never pushed).
const SMARTLEAD_CAMPAIGNS = { A: '', B: '' };
const SMARTLEAD_BATCH = 100;   // leads per request

// ---------------------------------------------------------------- Reply classification (02)
// OpenAI reads each reply into one class from REPLY_CLASSES. Blank key -> keyword rules only.
const OPENAI_API_KEY = '';
const OPENAI_MODEL   = 'gpt-4o-mini';
const OPENAI_URL     = 'https://api.openai.com/v1/chat/completions';
const REPLY_CLASSES  = ['interested', 'not_now', 'referral', 'unsubscribe', 'out_of_office', 'needs_human'];
// Below this confidence the model's answer is not trusted and a person reads the reply.
const MIN_AI_CONFIDENCE = 0.6;
// How many days out the follow-up task is due, by class.
const TASK_DUE_DAYS = { interested: 0, referral: 1, needs_human: 0, not_now: 60 };

// ---------------------------------------------------------------- Team notifications + call list
// A Slack (or Teams, or Google Chat) incoming-webhook URL. Blank -> shown, not posted.
const NOTIFY_WEBHOOK_URL = '';
// The morning call list: A-tier leads not yet contacted by phone, plus every interested or
// referral reply, ordered by who to ring first. Capped so it stays a list someone finishes.
const CALL_LIST_SIZE = 25;
const CALL_LIST_STATUSES = ['Replied - Interested', 'Replied - Referral', 'Qualified - A'];

// ---------------------------------------------------------------- Derived: do not edit below
const MODE = TEST_RUN !== true ? 'live' : (TEST_CAMPAIGN_ID.trim() !== '' ? 'test' : 'preview');
const ZOHO_AUTH_READY = ZOHO_CLIENT_ID.trim() !== '' && ZOHO_CLIENT_SECRET.trim() !== '' &&
                        ZOHO_REFRESH_TOKEN.trim() !== '';
const SMARTLEAD_READY = SMARTLEAD_API_KEY.trim() !== '';

const SETTINGS = {
  mode: MODE,
  test_campaign_id: TEST_CAMPAIGN_ID.trim(),
  test_cap: TEST_CAP,
  clay_fields: CLAY_FIELDS,
  scoring: SCORING,
  disqualify: DISQUALIFY,
  tiers: TIERS,
  seniority_from_title: SENIORITY_FROM_TITLE,
  personas: PERSONAS,
  recommended_action: RECOMMENDED_ACTION,
  enrich_tiers: ENRICH_TIERS,
  enrich_budget: ENRICH_BUDGET,
  credits_per_contact: CREDITS_PER_CONTACT,
  enrich_api_key: ENRICH_API_KEY,
  enrich_url: ENRICH_URL,
  reveal_phone: REVEAL_PHONE,
  verifier_api_key: VERIFIER_API_KEY,
  verifier_url: VERIFIER_URL,
  accept_statuses: ACCEPT_STATUSES,
  zoho_client_id: ZOHO_CLIENT_ID,
  zoho_client_secret: ZOHO_CLIENT_SECRET,
  zoho_refresh_token: ZOHO_REFRESH_TOKEN,
  zoho_api_base: ZOHO_API_BASE.replace(/\/+$/, ''),
  zoho_accounts_base: ZOHO_ACCOUNTS_BASE.replace(/\/+$/, ''),
  zoho_api_version: ZOHO_API_VERSION,
  zoho_duplicate_check: ZOHO_DUPLICATE_CHECK,
  zoho_triggers: ZOHO_TRIGGERS,
  lead_status_by_tier: LEAD_STATUS_BY_TIER,
  zoho_fields: ZOHO_FIELDS,
  owner_by_tier: OWNER_BY_TIER,
  reply_status: REPLY_STATUS,
  smartlead_api_key: SMARTLEAD_API_KEY,
  smartlead_api_base: SMARTLEAD_API_BASE.replace(/\/+$/, ''),
  smartlead_campaigns: SMARTLEAD_CAMPAIGNS,
  smartlead_batch: SMARTLEAD_BATCH,
  openai_api_key: OPENAI_API_KEY,
  openai_model: OPENAI_MODEL,
  openai_url: OPENAI_URL,
  reply_classes: REPLY_CLASSES,
  min_ai_confidence: MIN_AI_CONFIDENCE,
  task_due_days: TASK_DUE_DAYS,
  notify_webhook_url: NOTIFY_WEBHOOK_URL,
  call_list_size: CALL_LIST_SIZE,
  call_list_statuses: CALL_LIST_STATUSES,

  // Flags. Downstream nodes test these, never a key's emptiness.
  enrich_enabled: ENRICH_API_KEY.trim() !== '',
  verifier_enabled: VERIFIER_API_KEY.trim() !== '',
  zoho_auth_ready: ZOHO_AUTH_READY,
  zoho_enabled: ZOHO_AUTH_READY && MODE === 'live',
  smartlead_enabled: SMARTLEAD_READY && (MODE === 'live' || MODE === 'test'),
  ai_enabled: OPENAI_API_KEY.trim() !== '',
  notify_enabled: NOTIFY_WEBHOOK_URL.trim() !== '' && MODE !== 'preview'
};

// config sits IN the data path: whatever the trigger delivered is passed along untouched
// under `incoming`, one item in, one item out. A trigger with no payload (the schedule, a
// manual run) still produces one item, so $('config').first().json always resolves.
const incoming = $input.all().length ? $input.all().map((i) => i.json || {}) : [{}];
return incoming.map((payload) => ({ json: Object.assign({}, SETTINGS, { incoming: payload }) }));

// One clean reply per incoming Smartlead webhook. Smartlead's payload has changed shape over
// time, so each field is read from the names it has been sent under. The quoted history below
// the reply is cut off: the classifier reads what the person wrote, not our own email back.
const str = (v) => String(v === undefined || v === null ? '' : v).trim();
const firstOf = (o, keys) => { for (const k of keys) { if (str(o[k])) return str(o[k]); } return ''; };

function stripQuoted(text) {
  const lines = str(text).replace(/\r/g, '').split('\n');
  const out = [];
  for (const l of lines) {
    if (/^\s*>/.test(l) || /^On .+wrote:\s*$/.test(l) || /^-{2,}\s*Original Message/i.test(l) || /^From: /.test(l)) break;
    out.push(l);
  }
  return out.join('\n').trim();
}

return $input.all().map((item) => {
  const j = item.json || {};
  const payload = j.incoming || j;
  const b = payload.body !== undefined ? payload.body : payload;
  const msg = b.reply_message || {};
  const raw = typeof msg === 'string' ? msg : (msg.text || str(msg.html).replace(/<[^>]+>/g, ' '));
  return {
    json: {
      lead_email: firstOf(b, ['sl_lead_email', 'lead_email', 'from_email', 'email']).toLowerCase(),
      lead_name: firstOf(b, ['to_name', 'lead_name', 'from_name']),
      lead_id: firstOf(b, ['sl_email_lead_id', 'lead_id', 'sl_lead_id']),
      campaign_id: firstOf(b, ['campaign_id']),
      campaign_name: firstOf(b, ['campaign_name']),
      subject: firstOf(b, ['subject']),
      text: stripQuoted(raw),
      received_at: str(msg.time) || new Date().toISOString(),
      _source: payload._source || 'Smartlead webhook'
    }
  };
});

// The OpenAI request, one per reply. The model gets the subject and the reply text and nothing
// else, and must answer in a fixed JSON schema: one class from REPLY_CLASSES, a confidence, and
// a referral email only if the reply names one. It decides nothing downstream; the class does.
const cfg = $('config').first().json;
const classes = cfg.reply_classes || [];

const system = 'You classify replies to a B2B sales email. Answer with one class:\n' +
  '- interested: wants a call, a demo, pricing or more detail\n' +
  '- not_now: not interested yet, or asks to be contacted later\n' +
  '- referral: says someone else is the right person\n' +
  '- unsubscribe: asks not to be contacted again\n' +
  '- out_of_office: an automatic reply\n' +
  '- needs_human: anything else, including hostile or unclear replies\n' +
  'Only set referral_email if the reply contains that address. Never invent one.';

return $input.all().map((item) => {
  const r = item.json;
  return {
    json: Object.assign({}, r, {
      _ai_body: {
        model: cfg.openai_model,
        temperature: 0,
        messages: [
          { role: 'system', content: system },
          { role: 'user', content: 'Subject: ' + r.subject + '\n\n' + r.text.slice(0, 4000) }
        ],
        response_format: {
          type: 'json_schema',
          json_schema: {
            name: 'reply_class',
            strict: true,
            schema: {
              type: 'object',
              additionalProperties: false,
              required: ['class', 'confidence', 'referral_email'],
              properties: {
                class: { type: 'string', enum: classes },
                confidence: { type: 'number' },
                referral_email: { type: 'string' }
              }
            }
          }
        }
      }
    })
  };
});

// No OPENAI_API_KEY, so the keyword rules classify every reply. Anything they cannot place is
// "needs_human": a person reads it, rather than a rule guessing.
// The keyword rules, in order. First match wins, so the order is the policy: an unsubscribe
// beats everything, and an auto-reply is never mistaken for interest.
//
// Only the reply's own text is read, never the subject line: a reply's subject is "Re:" plus
// OUR subject, and a word in our own copy ("your Q4 pipeline") must not decide what the
// prospect meant. The one exception is the auto-reply check, where "Automatic reply:" in the
// subject is the strongest signal there is.
function keywordClass(subject, text) {
  const t = String(text || '').toLowerCase();
  const subj = String(subject || '').toLowerCase();
  const email = (String(text || '').match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i) || [''])[0].toLowerCase();
  const ooo = /(out of (the )?office|automatic reply|auto-?reply|on (annual )?leave|limited access to email|away until)/;
  const rules = [
    ['unsubscribe', (x) => /(unsubscribe|remove me|take me off|stop (emailing|contacting)|do not (email|contact)|opt(-| )?out)/.test(x)],
    ['out_of_office', (x) => ooo.test(x) || ooo.test(subj)],
    ['referral', (x) => /(not the right person|wrong person|loop in|reach out to|speak (to|with) (our|my)|better contact)/.test(x)],
    ['not_now', (x) => /(not (a )?priority|not right now|not now|circle back|next (quarter|year)|\bq[1-4]\b|later this year|not interested)/.test(x)],
    ['interested', (x) => /(interested|sounds good|let'?s (talk|chat|meet)|book|slots?|call|demo|pricing|how much|send (me )?(more|details)|timing is (actually )?good)/.test(x)]
  ];
  for (const [cls, test] of rules) {
    if (test(t)) {
      if (cls === 'referral' && !email) return { class: 'referral', confidence: 0.6, referral_email: '' };
      return { class: cls, confidence: 0.75, referral_email: cls === 'referral' ? email : '' };
    }
  }
  return { class: 'needs_human', confidence: 0.5, referral_email: '' };
}
return $input.all().map((item) => {
  const r = item.json;
  const k = keywordClass(r.subject, r.text);
  return { json: Object.assign({}, r, { class: k.class, confidence: k.confidence,
    referral_email: k.referral_email, classified_by: 'keyword rules' }) };
});

// Reads the model's answer, and does not trust it blindly:
//   * a class outside REPLY_CLASSES, or an answer that does not parse -> the keyword rules
//   * confidence below MIN_AI_CONFIDENCE -> needs_human, a person reads it
//   * a referral email that is not in the reply text is dropped, never used
//   * an unsubscribe the keyword rules catch always wins, whatever the model said
// The keyword rules, in order. First match wins, so the order is the policy: an unsubscribe
// beats everything, and an auto-reply is never mistaken for interest.
//
// Only the reply's own text is read, never the subject line: a reply's subject is "Re:" plus
// OUR subject, and a word in our own copy ("your Q4 pipeline") must not decide what the
// prospect meant. The one exception is the auto-reply check, where "Automatic reply:" in the
// subject is the strongest signal there is.
function keywordClass(subject, text) {
  const t = String(text || '').toLowerCase();
  const subj = String(subject || '').toLowerCase();
  const email = (String(text || '').match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i) || [''])[0].toLowerCase();
  const ooo = /(out of (the )?office|automatic reply|auto-?reply|on (annual )?leave|limited access to email|away until)/;
  const rules = [
    ['unsubscribe', (x) => /(unsubscribe|remove me|take me off|stop (emailing|contacting)|do not (email|contact)|opt(-| )?out)/.test(x)],
    ['out_of_office', (x) => ooo.test(x) || ooo.test(subj)],
    ['referral', (x) => /(not the right person|wrong person|loop in|reach out to|speak (to|with) (our|my)|better contact)/.test(x)],
    ['not_now', (x) => /(not (a )?priority|not right now|not now|circle back|next (quarter|year)|\bq[1-4]\b|later this year|not interested)/.test(x)],
    ['interested', (x) => /(interested|sounds good|let'?s (talk|chat|meet)|book|slots?|call|demo|pricing|how much|send (me )?(more|details)|timing is (actually )?good)/.test(x)]
  ];
  for (const [cls, test] of rules) {
    if (test(t)) {
      if (cls === 'referral' && !email) return { class: 'referral', confidence: 0.6, referral_email: '' };
      return { class: cls, confidence: 0.75, referral_email: cls === 'referral' ? email : '' };
    }
  }
  return { class: 'needs_human', confidence: 0.5, referral_email: '' };
}
const cfg = $('config').first().json;
const classes = cfg.reply_classes || [];
const src = $('build the AI request');

return $input.all().map((reply, i) => {
  let r = {};
  try { r = src.itemMatching(i).json; } catch (e) { r = (src.all()[i] || { json: {} }).json; }
  r = Object.assign({}, r);
  delete r._ai_body;
  const kw = keywordClass(r.subject, r.text);

  let ai = null;
  try {
    const content = reply.json.choices[0].message.content;
    ai = typeof content === 'string' ? JSON.parse(content) : content;
  } catch (e) { ai = null; }

  let out;
  if (!ai || !classes.includes(ai.class)) {
    out = Object.assign({}, kw, { classified_by: 'keyword rules (AI answer did not parse)' });
  } else if (Number(ai.confidence) < Number(cfg.min_ai_confidence || 0.6)) {
    out = { class: 'needs_human', confidence: Number(ai.confidence), referral_email: '',
      classified_by: 'AI (' + cfg.openai_model + '), below MIN_AI_CONFIDENCE' };
  } else {
    const ref = String(ai.referral_email || '').toLowerCase();
    out = { class: ai.class, confidence: Number(ai.confidence),
      referral_email: ref && r.text.toLowerCase().includes(ref) ? ref : '',
      classified_by: 'AI (' + cfg.openai_model + ')' };
  }
  if (kw.class === 'unsubscribe' && out.class !== 'unsubscribe') {
    out = Object.assign({}, kw, { classified_by: 'keyword rules (unsubscribe always wins)' });
  }
  return { json: Object.assign(r, out) };
});

// What happens next for each reply, decided from its class and nothing else:
//
//   interested   Zoho status + a task due today + the team is told     (a person calls)
//   referral     Zoho status + a task to contact the named person + told
//   needs_human  Zoho status + a task due today + told                  (a person reads it)
//   not_now      Zoho status + a task in TASK_DUE_DAYS.not_now days
//   unsubscribe  Zoho Email_Opt_Out + status, and suppressed in Smartlead
//   out_of_office nothing: Smartlead carries on with the sequence
//
// The bot never replies to anyone. Every reply that needs an answer becomes a person's task.
const cfg = $('config').first().json;
const S = cfg.reply_status || {};
const due = cfg.task_due_days || {};
const today = new Date();
const dayPlus = (n) => new Date(today.getTime() + Number(n || 0) * 86400000).toISOString().slice(0, 10);

const subjects = {
  interested: (r) => 'Call ' + (r.lead_name || r.lead_email) + ': replied interested',
  referral: (r) => 'Contact the referral from ' + (r.lead_name || r.lead_email) + (r.referral_email ? ': ' + r.referral_email : ''),
  needs_human: (r) => 'Read and answer ' + (r.lead_name || r.lead_email) + "'s reply",
  not_now: (r) => 'Follow up with ' + (r.lead_name || r.lead_email) + ': asked for later'
};

return $input.all().map((item) => {
  const r = Object.assign({}, item.json);
  const c = r.class;
  r._write_zoho = c !== 'out_of_office';
  r._status = S[c] || '';
  r._opt_out = c === 'unsubscribe';
  r._suppress = c === 'unsubscribe';
  r._notify = ['interested', 'referral', 'needs_human'].includes(c);
  r._task = subjects[c] ? {
    subject: subjects[c](r),
    due_date: dayPlus(due[c]),
    priority: c === 'not_now' ? 'Normal' : 'High',
    description: 'Reply (' + c + ', ' + r.classified_by + '): "' + r.text.slice(0, 500) + '"'
  } : null;
  r._action = c === 'out_of_office' ? 'ignored: auto-reply, the sequence continues'
    : c === 'unsubscribe' ? 'opted out in Zoho, unsubscribed in Smartlead'
    : 'Zoho status "' + r._status + '" and a task due ' + r._task.due_date;
  return { json: r };
});

// One upsert for every reply that changes the lead: its Lead_Status, and Email_Opt_Out for an
// unsubscribe. Matched on email, so the lead that workflow 01 created is updated. If Clay never
// created it, the upsert creates it, which is why Last_Name is always sent.
//
// The tasks cannot be created yet: a Zoho task hangs off the lead's record id, and the id is
// what this upsert returns. `build the tasks` pairs them after the write.
const cfg = $('config').first().json;
const replies = $input.all().map((i) => i.json).filter((r) => r._write_zoho);

const records = replies.slice(0, 100).map((r) => {
  const parts = String(r.lead_name || '').split(/\s+/).filter(Boolean);
  const rec = {
    Email: r.lead_email,
    Last_Name: parts.slice(1).join(' ') || parts[0] || r.lead_email.split('@')[0],
    Lead_Status: r._status
  };
  if (parts.length > 1) rec.First_Name = parts[0];
  if (r._opt_out) rec.Email_Opt_Out = true;
  return rec;
});

return [{
  json: {
    _count: records.length,
    _replies: replies.map((r) => ({ email: r.lead_email, name: r.lead_name, class: r.class, task: r._task })),
    _zoho: {
      url: cfg.zoho_api_base + '/crm/' + cfg.zoho_api_version + '/Leads/upsert',
      body: { data: records, duplicate_check_fields: ['Email'], trigger: cfg.zoho_triggers || [] }
    }
  }
}];

// Zoho was not written: TEST_RUN is true, the OAuth values are blank, or no reply changed a
// lead. The exact upsert, and every task that would follow it, are here.
const cfg = $('config').first().json;
const j = $input.first().json;
return [{
  json: {
    _outcome: 'preview: nothing written to Zoho',
    _reason: j._count === 0 ? 'no reply changes a lead (out-of-office only)'
      : (cfg.mode !== 'live' ? 'TEST_RUN is true, mode ' + cfg.mode
        : 'ZOHO_CLIENT_ID / ZOHO_CLIENT_SECRET / ZOHO_REFRESH_TOKEN is blank'),
    would_upsert: j._zoho.body,
    then_tasks: j._replies.filter((r) => r.task).map((r) => Object.assign({ lead: r.email }, r.task))
  }
}];

// Reads the access token out of the refresh-token exchange. Zoho answers a failed refresh with
// HTTP 200 and an `error` key in the body, so the body is checked here, not just the status.
function readToken(res, request) {
  if (res.error || !res.access_token) {
    return {
      _authed: false,
      _why: res.error ? 'Zoho refused the refresh: ' + res.error : 'Zoho returned no access_token',
      _hint: res.error === 'invalid_client'
        ? 'ZOHO_CLIENT_ID and ZOHO_CLIENT_SECRET belong to a different data centre than ZOHO_ACCOUNTS_BASE'
        : res.error === 'invalid_code'
        ? 'the refresh token was revoked, or issued for different scopes'
        : 'check ZOHO_ACCOUNTS_BASE matches the region the Self Client was registered in'
    };
  }
  return Object.assign({}, request, { _authed: true, _access_token: res.access_token });
}
return [{ json: readToken($input.first().json || {}, $('build the Zoho updates').first().json) }];

// The refresh-token exchange failed, so nothing was written. `_why` and `_hint` say which of
// the usual causes it is.
const j = $input.first().json || {};
return [{ json: { _outcome: 'could not authenticate with Zoho: nothing written', _why: j._why, _hint: j._hint } }];

// Pairs each upsert result with the reply it was sent for, and builds one Zoho task per reply
// that needs a person, attached to the lead's record id. A record Zoho refused gets no task,
// and is listed by name instead of silently dropping out.
const cfg = $('config').first().json;
const sent = $('build the Zoho updates').first().json;
const token = $('read the access token').first().json._access_token;
const res = $input.first().json || {};
const results = Array.isArray(res.data) ? res.data : [];
const withStatus = sent._replies;

const tasks = [];
const refused = [];
results.forEach((r, i) => {
  const reply = withStatus[i] || {};
  if (r.code !== 'SUCCESS') { refused.push({ email: reply.email, code: r.code, message: r.message }); return; }
  if (!reply.task) return;
  tasks.push({
    Subject: reply.task.subject,
    Due_Date: reply.task.due_date,
    Priority: reply.task.priority,
    Status: 'Not Started',
    Description: reply.task.description,
    What_Id: { id: r.details && r.details.id },
    $se_module: 'Leads'
  });
});

return [{
  json: {
    _access_token: token,
    _task_count: tasks.length,
    leads_updated: results.filter((r) => r.code === 'SUCCESS').length,
    refused: refused,
    _tasks: {
      url: cfg.zoho_api_base + '/crm/' + cfg.zoho_api_version + '/Tasks',
      body: { data: tasks, trigger: cfg.zoho_triggers || [] }
    }
  }
}];

// Zoho refused the whole request. A visible step with the response on it, never a run that
// half-succeeded and said nothing. The usual three: INVALID_TOKEN (wrong data centre),
// MANDATORY_NOT_FOUND (the layout needs a field this does not send), INVALID_DATA (a
// Lead_Status in LEAD_STATUS_BY_TIER that does not exist in the org).
const j = $input.first().json || {};
const err = j.error || j;
return [{
  json: {
    _outcome: 'Zoho write failed: nothing was written',
    zoho_response: typeof err === 'string' ? err : JSON.stringify(err).slice(0, 600)
  }
}];

// The leads are updated in Zoho, and the tasks, if any were due, are created. Zoho answers the
// task call per record too, so each is read rather than trusting the 200.
const built = $('build the tasks').first().json;
let taskResults = [];
try {
  const res = $('Zoho CRM - create the tasks').first().json || {};
  taskResults = (res.data || []).map((r) => ({ code: r.code, id: r.details && r.details.id, message: r.code === 'SUCCESS' ? '' : r.message }));
} catch (e) { /* no tasks were due */ }
return [{
  json: {
    _outcome: 'Zoho updated',
    leads_updated: built.leads_updated,
    refused: built.refused,
    tasks_created: taskResults.filter((t) => t.code === 'SUCCESS').length,
    tasks_refused: taskResults.filter((t) => t.code !== 'SUCCESS')
  }
}];

// Every unsubscribe, as a Smartlead call: POST /leads/{lead_id}/unsubscribe takes the lead out
// of every campaign, not just the one they replied to. A reply with no lead id cannot be
// matched, and is listed for a person to remove by hand rather than skipped silently.
const cfg = $('config').first().json;
const unsubs = $input.all().map((i) => i.json).filter((r) => r._suppress);
if (!unsubs.length) return [{ json: { _none: true, _reason: 'no unsubscribes in this batch' } }];
return unsubs.map((r) => ({
  json: {
    email: r.lead_email,
    lead_id: r.lead_id,
    _url: r.lead_id ? cfg.smartlead_api_base + '/leads/' + encodeURIComponent(r.lead_id) + '/unsubscribe' : '',
    _reason: r.lead_id ? '' : 'no Smartlead lead id on the webhook: remove this lead by hand'
  }
}));

// No Smartlead call was made: a preview run, no SMARTLEAD_API_KEY, no lead id, or nobody
// unsubscribed. Each unsubscribe that would have been sent is listed.
const cfg = $('config').first().json;
const items = $input.all().map((i) => i.json);
return [{
  json: {
    _outcome: 'preview: no unsubscribe sent to Smartlead',
    _reason: items[0] && items[0]._none ? items[0]._reason
      : (!cfg.smartlead_enabled ? (cfg.mode === 'preview' ? 'TEST_RUN is true' : 'SMARTLEAD_API_KEY is blank') : 'no lead id'),
    would_unsubscribe: items.filter((u) => !u._none).map((u) => ({ email: u.email, url: u._url, note: u._reason }))
  }
}];

// Smartlead confirmed (or refused) each unsubscribe. A refusal carries the response.
const src = $('suppressing in Smartlead?');
return $input.all().map((reply, i) => {
  let u = {};
  try { u = src.itemMatching(i).json; } catch (e) { u = (src.all(0)[i] || { json: {} }).json; }
  const b = reply.json || {};
  const failed = !!(b.error || b.ok === false);
  return { json: { _outcome: failed ? 'Smartlead refused the unsubscribe' : 'unsubscribed in Smartlead',
    email: u.email, lead_id: u.lead_id, error: failed ? JSON.stringify(b.error || b).slice(0, 300) : '' } };
});

// One message to the team for the replies a person has to act on now: interested, referral,
// needs a human. It quotes the reply, so nobody has to open Smartlead to know what was said.
const cfg = $('config').first().json;
const hot = $input.all().map((i) => i.json).filter((r) => r._notify);
const label = { interested: 'Interested', referral: 'Referral', needs_human: 'Needs a person' };
const lines = hot.map((r) => '• ' + label[r.class] + ': ' + (r.lead_name || r.lead_email) + ' <' + r.lead_email + '>' +
  (r.referral_email ? ' → ' + r.referral_email : '') + '\n   "' + r.text.replace(/\s+/g, ' ').slice(0, 200) + '"');
const text = (cfg.mode === 'live' ? '' : '[' + cfg.mode.toUpperCase() + '] ') +
  hot.length + ' repl' + (hot.length === 1 ? 'y needs' : 'ies need') + ' a person:\n' + lines.join('\n');
return [{ json: { _count: hot.length, text: text, _notify_body: { text: text } } }];

// Not posted: a preview run, no NOTIFY_WEBHOOK_URL, or nothing needed a person. The message
// that would have gone is `text`.
const j = $input.first().json;
return [{ json: { _outcome: 'alert shown, not posted', replies: j._count, text: j.text } }];

// Posted to the team channel. A webhook that answered with an error is reported, not assumed.
const b = $input.first().json || {};
const failed = !!(b.error || b.ok === false);
return [{ json: { _outcome: failed ? 'the team channel refused the post' : 'posted to the team channel',
  error: failed ? JSON.stringify(b.error || b).slice(0, 300) : '' } }];

// Zoho is not connected, so an invented pipeline stands in, in the same shape `read the leads`
// produces: two interested replies, a referral, and two A-tier leads from earlier runs.
const now = Date.now();
const ago = (h) => new Date(now - h * 3600000).toISOString();
const rows = [
  { name: 'Dana Reyes', company: 'Ledgerly', title: 'VP of Sales', phone: '+1234567890', email: 'user@example.com', status: 'Replied - Interested', score: 95, action: 'Call today, then sequence A', modified: ago(14) },
  { name: 'Jamie Cole', company: 'Stackmart', title: 'RevOps Lead', phone: '', email: 'user@example.com', status: 'Replied - Referral', score: null, action: '', modified: ago(20) },
  { name: 'Owen Park', company: 'Brightline Analytics', title: 'Head of Sales', phone: '+1234567890', email: 'user@example.com', status: 'Replied - Interested', score: 70, action: 'Call within 24 hours, then sequence A', modified: ago(3) },
  { name: 'Elena Rossi', company: 'Corebill', title: 'VP Sales', phone: '+1234567890', email: 'user@example.com', status: 'Qualified - A', score: 92, action: 'Call within 24 hours, then sequence A', modified: ago(40) },
  { name: 'Victor Hale', company: 'Shipwise', title: 'Chief Revenue Officer', phone: '', email: 'user@example.com', status: 'Qualified - A', score: 100, action: 'Call today, then sequence A', modified: ago(60) }
];
return [{ json: { source: 'demo pipeline (invented)', rows: rows, more: false } }];

// Reads the token, then builds one COQL query for everyone who belongs on today's list: the
// Lead_Status values in CALL_LIST_STATUSES. COQL returns at most 2000 rows a call and 200 by
// default; the list is capped far below that.
function readToken(res, request) {
  if (res.error || !res.access_token) {
    return {
      _authed: false,
      _why: res.error ? 'Zoho refused the refresh: ' + res.error : 'Zoho returned no access_token',
      _hint: res.error === 'invalid_client'
        ? 'ZOHO_CLIENT_ID and ZOHO_CLIENT_SECRET belong to a different data centre than ZOHO_ACCOUNTS_BASE'
        : res.error === 'invalid_code'
        ? 'the refresh token was revoked, or issued for different scopes'
        : 'check ZOHO_ACCOUNTS_BASE matches the region the Self Client was registered in'
    };
  }
  return Object.assign({}, request, { _authed: true, _access_token: res.access_token });
}
const cfg = $('config').first().json;
const t = readToken($input.first().json || {}, {});
if (!t._authed) return [{ json: t }];

const F = cfg.zoho_fields || {};
const fields = ['First_Name', 'Last_Name', 'Company', 'Phone', 'Email', 'Lead_Status', 'Designation', 'Modified_Time'];
if (F.fit_score) fields.push(F.fit_score);
if (F.tier) fields.push(F.tier);
if (F.recommended_action) fields.push(F.recommended_action);
const statuses = (cfg.call_list_statuses || []).map((s) => "'" + String(s).replace(/'/g, "\\'") + "'").join(', ');

return [{
  json: Object.assign(t, {
    _coql: {
      url: cfg.zoho_api_base + '/crm/' + cfg.zoho_api_version + '/coql',
      body: { select_query: 'select ' + fields.join(', ') + ' from Leads where Lead_Status in (' + statuses +
        ') order by Modified_Time desc limit 200' }
    }
  })
}];

// The refresh-token exchange failed, so nothing was written. `_why` and `_hint` say which of
// the usual causes it is.
const j = $input.first().json || {};
return [{ json: { _outcome: 'could not authenticate with Zoho: nothing written', _why: j._why, _hint: j._hint } }];

// COQL's answer as plain rows, in the same shape the demo pipeline uses, so ranking is one code
// path either way. An empty result is { } with no data key, which reads as an empty list.
const cfg = $('config').first().json;
const F = cfg.zoho_fields || {};
const res = $input.first().json || {};
const rows = (res.data || []).map((l) => ({
  name: [l.First_Name, l.Last_Name].filter(Boolean).join(' '),
  company: l.Company || '',
  title: l.Designation || '',
  phone: l.Phone || '',
  email: l.Email || '',
  status: l.Lead_Status || '',
  score: F.fit_score ? Number(l[F.fit_score] || 0) : null,
  action: F.recommended_action ? (l[F.recommended_action] || '') : '',
  modified: l.Modified_Time || ''
}));
return [{ json: { source: 'Zoho CRM', rows: rows, more: !!(res.info && res.info.more_records) } }];

// The COQL read failed, so no call list was built today. The response says why: most often
// INVALID_QUERY (a field in ZOHO_FIELDS that does not exist) or OAUTH_SCOPE_MISMATCH (the
// refresh token lacks ZohoCRM.coql.READ).
const j = $input.first().json || {};
return [{ json: { _outcome: 'could not read Zoho: no call list today', zoho_response: JSON.stringify(j.error || j).slice(0, 600) } }];

// Today's call list, in the order to ring: every interested reply first (the most recent at the
// top, they are warmest), then referrals, then A-tier leads by fit score. Capped at
// CALL_LIST_SIZE so it is a list someone can finish before lunch. A lead with no phone stays on
// it, marked "email instead", rather than disappearing.
const cfg = $('config').first().json;
const S = cfg.reply_status || {};
const merged = $input.all().map((i) => i.json);
const src = merged.find((m) => m.rows) || { rows: [], source: 'none' };

const rank = (r) => r.status === S.interested ? 0 : (r.status === S.referral ? 1 : 2);
const sorted = src.rows.slice().sort((a, b) =>
  rank(a) - rank(b) ||
  (rank(a) < 2 ? String(b.modified).localeCompare(String(a.modified)) : (Number(b.score || 0) - Number(a.score || 0))));
const list = sorted.slice(0, Number(cfg.call_list_size || 25));

const why = (r) => r.status === S.interested ? 'replied interested'
  : r.status === S.referral ? 'referred to by a prospect' : 'A tier, fit ' + (r.score === null ? '?' : r.score);
const lines = list.map((r, i) => (i + 1) + '. ' + r.name + ', ' + r.company + (r.title ? ' (' + r.title + ')' : '') +
  ': ' + why(r) + '. ' + (r.phone ? r.phone : 'no phone, email ' + r.email) + (r.action ? '. ' + r.action : ''));
const day = new Date().toISOString().slice(0, 10);
const text = (cfg.mode === 'live' ? '' : '[' + cfg.mode.toUpperCase() + '] ') + 'Call list for ' + day +
  ' (' + list.length + (sorted.length > list.length ? ' of ' + sorted.length : '') + ', from ' + src.source + ')\n' + lines.join('\n') +
  (src.more ? '\nZoho had more rows than one page: the list is from the most recent 200.' : '');

return [{ json: { source: src.source, count: list.length, list: list.map((r) => Object.assign({ why: why(r) }, r)),
  text: text, _notify_body: { text: text } } }];

// Not posted: a preview run or no NOTIFY_WEBHOOK_URL. The list is `text`, and each row with why
// it is there is in `list`.
const j = $input.first().json;
return [{ json: { _outcome: 'call list shown, not posted', count: j.count, text: j.text, list: j.list } }];

// Posted to the team channel. A webhook that answered with an error is reported, not assumed.
const b = $input.first().json || {};
const failed = !!(b.error || b.ok === false);
return [{ json: { _outcome: failed ? 'the team channel refused the post' : 'posted to the team channel',
  error: failed ? JSON.stringify(b.error || b).slice(0, 300) : '' } }];
